require_once dirname(__DIR__) . '/bootstrap.php';require_method('GET');header('Cache-Control: no-store, private');$u=current_user();
$s=db()->prepare("SELECT a.public_id id,a.account_name accountName,a.sender_name senderName,a.sender_email email,a.host,a.port,a.encryption,a.username,a.status,a.is_active isActive,a.daily_limit dailyLimit,a.hourly_limit hourlyLimit,a.per_minute_limit perMinuteLimit,a.sending_interval_seconds sendingInterval,a.reply_tracking_enabled replyTracking,a.imap_host imapHost,a.imap_port imapPort,a.imap_encryption imapEncryption,a.imap_username imapUsername,a.imap_last_checked_at imapLastCheckedAt,a.imap_last_error imapLastError,(SELECT COALESCE(SUM(sc.sent_count),0) FROM smtp_send_counters sc WHERE sc.tenant_id=a.tenant_id AND sc.smtp_account_id=a.id AND sc.window_type='DAY' AND sc.window_start=UTC_DATE()) sentToday,a.last_tested_at lastTestedAt,a.last_error lastError FROM smtp_accounts a WHERE a.tenant_id=? ORDER BY a.created_at DESC");$s->execute([$u['tenant_id']]);$rows=$s->fetchAll();foreach($rows as &$r){$r['isActive']=(bool)$r['isActive'];$r['replyTracking']=(bool)$r['replyTracking'];$r['passwordConfigured']=true;$r['imapPasswordConfigured']=!empty($r['imapHost']);}respond($rows);
